// Einmal nach dem Scan des Fertigungsauftrags, vor dem Test-Start.
// Demo-Zuordnung; die reale Datenquelle wird hier abgefragt.
string auftrag = (Auftrag ?? "").Trim();
string programm, artikel;
if (auftrag.StartsWith("A", StringComparison.OrdinalIgnoreCase))
{ programm = "Programm A"; artikel = "11111"; }
else if (auftrag.StartsWith("B", StringComparison.OrdinalIgnoreCase))
{ programm = "Programm B"; artikel = "22222"; }
else if (auftrag.StartsWith("C", StringComparison.OrdinalIgnoreCase))
{ programm = "Programm C"; artikel = "33333"; }
else if (auftrag.StartsWith("D", StringComparison.OrdinalIgnoreCase))
{ programm = "Programm D"; artikel = "44444"; }
else return Error("Unbekannter Fertigungsauftrag: " + auftrag);
SelectTest(programm, null, auftrag, "Artikel=" + artikel);
return Pass(programm);
